 "SLET":"bbs.bbsmtrl.java", 
 "acton":"chkpwd", 
 "BMID":mtrlID, 
 "pw": function(){
 if(jQuery("#publicKeyModulus").size() > 0 && jQuery("#publicKeyModulus").val() !=""){
 var rsaPublicKeyModulus = jQuery("#publicKeyModulus");
 var rsaPublicKeyExponent = jQuery("#publicKeyExponent");
 if(rsaPublicKeyModulus.length != 1){
 rsaPublicKeyModulus = false; 
 }else{
 rsaPublicKeyModulus = rsaPublicKeyModulus.val();
 }
 if(rsaPublicKeyExponent.length != 1){
 rsaPublicKeyExponent = false; 
 }else{
 rsaPublicKeyExponent = rsaPublicKeyExponent.val();
 }
 if(rsaPublicKeyModulus && rsaPublicKeyExponent && typeof("RSAKey") != 'undefined'){
 var rsa = new RSAKey();
 rsa.setPublic(rsaPublicKeyModulus, rsaPublicKeyExponent);
 var plain = jQuery("#mtrl_passwd").val();
 if(plain){
 var crypted = rsa.encrypt(plain);
 cryptedPassword = crypted;
 }
 return crypted;
 }
 } else {
 return jQuery("#mtrl_passwd").val();
 }
 }, 
 "type":0, 
 "K":KeyValue,
 "__cryptedParams__": "pw,"
 },
 dataType: "xml",
 success: function(data, status){
 var code = jQuery("code", data).text(); 
 if(eval(code) == 0) {
 if(jQuery("#publicKeyModulus").size() > 0 && jQuery("#publicKeyModulus").val() !=""){
 tmpParam += "&password=" + cryptedPassword;
 tmpParam += "&__cryptedParams__=password,";
 }else{
 tmpParam += "&password=" + encodeURIComponent(jQuery("#mtrl_passwd").val());
 }
 BMWriteWin(tmpParam, tmpType);
 } else if(eval(code) == 1) { // Password Check..
 jQuery("#mtrl_passwd").val("");
 jQuery("#addFucView").hide();
 alert(RC_PASSWORD_NOT_MSG);
 } else // for exception
 alert("ERROR CODE:::"+code);
 },
 error:function(data, status) {
 BBSMtrlList.displayError("[Error]toRead()::"+status+"\n\n"+data.responseText);
 },
 async:false
 });
}
