 type:"post",
 cache:false,
 url:"/servlet/HIServlet",
 data: {
 "SLET":"bbs.bbsmtrl.java", 
 "acton":"chkpwd", 
 "BMID":mtrlID, 
 "pw": function(){
 if(jQuery("#publicKeyModulus").size() > 0 && jQuery("#publicKeyModulus").val() !=""){
 var rsaPublicKeyModulus = jQuery("#publicKeyModulus");
 var rsaPublicKeyExponent = jQuery("#publicKeyExponent");
 if(rsaPublicKeyModulus.length != 1){
 rsaPublicKeyModulus = false; 
 }else{
 rsaPublicKeyModulus = rsaPublicKeyModulus.val();
