 if(rsaPublicKeyModulus && rsaPublicKeyExponent && typeof("RSAKey") != 'undefined'){
 var rsa = new RSAKey();
 rsa.setPublic(rsaPublicKeyModulus, rsaPublicKeyExponent);
 var plain = jQuery("#mtrl_passwd").val();
 if(plain){
