function backToList(delFlag)
{
 if(parent)
 {
 if((delFlag || parent.lastDataValueForList["FILTER"] == "unread" || parent.lastDataValueForList["UNREAD"] == "on") 
 && jQuery("#mtrl_list_items", parent.document).find("#mtrlchk").size() == 1) {
 var pno = parent.lastDataValueForList["PNO"];
 if(pno > 1) {
 pno--;
 parent.lastDataValueForList["PNO"] = pno;
 }
 }
 if(parent.BBSMtrlList) {
 parent.BBSMtrlList.releaseBBSMtrlListUI(false);
 parent.BBSMtrlList.refreshMtrlList();
 }
 self.close();
 }
}
